import {ownRecord} from './state-validation.mjs';
export const biologyLabActivity={id:'biology-lab',stage:'7y',key:'7y:biology-lab',area:'Ciencia',type:'digital',label:'9–12 años · registros ficticios',kind:'interactive',title:'Biología · Dos bandejas, una pregunta',unit:'Dos bandejas, una pregunta',copy:'Construye una comparación de plantas con fichas de luz y agua; anticipa, consulta registros y revisa qué puedes concluir.',goal:'Distinguir una comparación que mantiene condiciones de otra que mezcla cambios, con límites de interpretación.',duration:'Una comparación o varias, a tu ritmo',support:'Lectura acompañada si hace falta; botones y teclado',transfer:'Dibuja dos plantas imaginarias y las condiciones que mantendrías iguales. No cambies el cuidado de plantas reales.'};
// Authored fictional records, never a growth calculator or plant-care recommendation.
export const biologyTrays=Object.freeze({a:{name:'A',light:8,water:30,leaves:6},b:{name:'B',light:12,water:30,leaves:9},c:{name:'C',light:8,water:60,leaves:8},d:{name:'D',light:12,water:60,leaves:10}});
export const biologyPredictions={left:'Más hojas nuevas a la izquierda',equal:'El mismo número',right:'Más hojas nuevas a la derecha',unknown:'No tengo suficiente información para anticiparlo'};
export const biologyQuestions={light:'Comparar horas de luz',water:'Comparar agua aportada'};
export const biologyReasons={bounded:'Describo estos registros; repetiría la comparación antes de generalizar.',control:'Reviso si solo cambia el factor de mi pregunta.',always:'La condición mayor siempre hace crecer mejor cualquier planta.'};
export const newBiologyLab=()=>({open:true,page:'guide',question:'light',left:'a',right:'d',prediction:null,tested:null,original:null,reason:null,reviewed:false,hint:false});
const member=(map,v)=>typeof v==='string'&&Object.hasOwn(map,v);
function trial(t){ownRecord(t,['question','left','right','prediction']);if(!member(biologyQuestions,t.question)||!member(biologyTrays,t.left)||!member(biologyTrays,t.right)||!member(biologyPredictions,t.prediction))throw Error('Invalid biology trial');return {question:t.question,left:t.left,right:t.right,prediction:t.prediction};}
const same=(a,b)=>a&&b&&['question','left','right','prediction'].every(k=>a[k]===b[k]);
export function validateBiologyLab(s){ownRecord(s,['open','page','question','left','right','prediction','tested','original','reason','reviewed','hint']);if(typeof s.open!=='boolean'||!['guide','edit','close'].includes(s.page)||!member(biologyQuestions,s.question)||!member(biologyTrays,s.left)||!member(biologyTrays,s.right)||!(s.prediction===null||member(biologyPredictions,s.prediction))||!(s.reason===null||member(biologyReasons,s.reason))||typeof s.reviewed!=='boolean'||typeof s.hint!=='boolean')throw Error('Invalid biology state');const tested=s.tested===null?null:trial(s.tested),original=s.original===null?null:trial(s.original);if(tested&&(!original||!same(tested,s))||s.reason&&!tested||s.reviewed&&(!tested||!s.reason)||s.page==='close'&&(!tested||!s.reviewed||!s.reason))throw Error('Inconsistent biology state');return {...s,tested,original};}
export function compareBiology(t){const a=biologyTrays[t.left],b=biologyTrays[t.right];if(!a||!b||!member(biologyQuestions,t.question))throw Error('Unknown comparison');const target=t.question,other=target==='light'?'water':'light',changesTarget=a[target]!==b[target],sameOther=a[other]===b[other];return {left:a.leaves,right:b.leaves,outcome:a.leaves===b.leaves?'equal':a.leaves>b.leaves?'left':'right',controlled:changesTarget&&sameOther,changesTarget,sameOther};}
export function changeBiology(s,field,value){if(s.page!=='edit'||!['question','left','right','prediction'].includes(field))return false;const maps={question:biologyQuestions,left:biologyTrays,right:biologyTrays,prediction:biologyPredictions};if(!member(maps[field],value)||s[field]===value)return false;s[field]=value;s.tested=null;s.reason=null;s.reviewed=false;s.hint=false;return true;}
export function testBiology(s){if(s.page!=='edit'||!s.prediction)return false;const t=trial({question:s.question,left:s.left,right:s.right,prediction:s.prediction});s.tested=t;s.original??={...t};s.reason=null;s.reviewed=false;return true;}
export function explainBiology(s){if(!s.tested)return 'Abre los registros después de anticipar.';const r=compareBiology(s.tested);const relation=r.controlled?'En las fichas solo cambia el factor elegido; las otras condiciones declaradas se mantienen. Es una comparación pertinente para esta pregunta.':!r.changesTarget?'El factor de tu pregunta no cambia. Este par no permite contrastarlo.':'También cambia el otro factor. No podemos separar su contribución con este par.';const limit='Son registros inventados de dos bandejas, sin réplicas de cada condición ni medida de variabilidad. No prueban una regla general ni que más hojas signifique mejor salud.';return relation+' '+(s.reason==='always'?'Esa conclusión va más allá de los datos. Más agua o luz no siempre es mejor para cualquier planta. ':s.reason==='bounded'?'Limitar la conclusión a estos registros es pertinente. ':s.reason==='control'?'Mirar qué cambia es una estrategia pertinente. ':'Elige una explicación para contrastarla. ')+limit;}
export function closeBiology(s){if(s.page!=='edit'||!s.tested||!s.reason||!s.reviewed)return false;s.page='close';return true;}
const plantArt=()=>`<svg class="balance-diagram" viewBox="0 0 420 140" aria-hidden="true"><rect x="35" y="93" width="350" height="32" rx="8" fill="#a7754d"/>${[100,210,320].map(x=>`<path d="M${x} 94V42m0 27q-40-35-38-12q15 24 38 12m0-15q36-31 35-10q-12 21-35 10" fill="#a2b68d" stroke="#215747" stroke-width="4"/>`).join('')}</svg>`;
export function renderBiologyLab(root,state,{back,finish}){const s=state.biologyLab??=newBiologyLab();const redraw=(id='#biology-title')=>{renderBiologyLab(root,state,{back,finish});root.querySelector(id)?.focus();};const buttons=(map,value,attr)=>`<div class="balance-choices">${Object.entries(map).map(([id,label])=>`<button type="button" class="action secondary" ${attr}="${id}" aria-pressed="${id===value}">${label}</button>`).join('')}</div>`;const options=Object.fromEntries(Object.entries(biologyTrays).map(([id,t])=>[id,`Bandeja ${t.name}: ${t.light} h de luz/día · ${t.water} mL de agua/día`]));const card=(id,side,show)=>{const t=biologyTrays[id];return `<article class="balance-record"><h5>${side} · bandeja ${t.name}</h5>${plantArt()}<p>3 plantas de judía. Luz: <strong>${t.light} horas al día</strong>. Agua aportada a la bandeja: <strong>${t.water} mL al día</strong>.</p>${show?`<p><strong>${t.leaves} hojas nuevas</strong> en total entre las tres plantas al terminar 7 días.</p>`:'<p>Registro de hojas todavía cerrado.</p>'}</article>`;};const summary=(t,label)=>{const r=compareBiology(t);return `<article class="balance-record"><h5>${label}</h5><p>${biologyQuestions[t.question]} · ${biologyTrays[t.left].name} frente a ${biologyTrays[t.right].name}.</p><p>Anticipación: ${biologyPredictions[t.prediction]}.</p><p>Registro ficticio: ${r.left} frente a ${r.right} hojas nuevas. ${r.controlled?'Solo cambia el factor elegido.':'No aísla el factor elegido.'}</p></article>`;};
 root.innerHTML=`<section class="balance-studio biology-lab"><p class="eyebrow">Biología · 9–12 años · lectura acompañada si hace falta</p><h4 id="biology-title" tabindex="-1">Dos bandejas, una pregunta</h4><p><strong>Archivo inventado, no experimento real ni simulación de crecimiento.</strong> Construye una comparación con fichas. Elegir otra bandeja abre otro registro ya escrito: no calculamos cómo crecerá una planta.</p><details class="balance-assumptions"><summary>Qué se mantiene y qué no sabemos</summary><p>En la historia, cada bandeja tiene tres judías de la misma variedad y edad, cada una con dos hojas iniciales. Se declara igual sustrato, recipiente, temperatura, espacio, aire, intensidad y tipo de lámpara y duración de observación (7 días). Cambian las horas de luz o el agua aportada. Contamos hojas nuevas completamente desplegadas, sumadas entre tres plantas.</p><p>No hay repeticiones independientes de cada condición ni datos de variación entre plantas. Las cifras no son una receta de riego ni demuestran salud, fotosíntesis o rendimiento. El dibujo simboliza tres plantas: no representa su tamaño ni el número observado de hojas.</p></details>${s.page==='guide'?`<p>Las plantas se relacionan con condiciones de su entorno, como luz y agua. Aquí no buscamos una receta de crecimiento: aprenderemos a elegir qué registros conviene comparar.</p><p>Elige una pregunta, coloca fichas a izquierda y derecha y anticipa. Después podrás consultar los datos inventados, revisar tu par y contrastar una explicación. Tu primer par consultado quedará conservado.</p><button type="button" class="action primary" id="biology-start">Construir mi comparación</button>`:s.page==='close'?`<h5>Mi comparación inicial y mi revisión</h5><div class="balance-records">${summary(s.original,'Primer registro conservado')}${summary(s.tested,'Último registro consultado')}</div><p>${explainBiology(s)}</p><p>Se puede conservar una comparación pertinente o cambiarla sin penalización. Para investigar de verdad harían falta más bandejas comparables y observaciones repetidas.</p><p><strong>Fuera de pantalla:</strong> dibuja dos plantas imaginarias y anota qué mantendrías igual para comparar una condición. Puedes observar una planta desde lejos con un adulto, sin cambiar su cuidado, arrancar hojas ni tocar animales.</p><div class="controls"><button type="button" class="action secondary" id="biology-revise">Revisar mi estrategia</button><button type="button" class="action primary" id="biology-finish">Terminar por hoy</button></div>`:`<p>1. Elige la pregunta. 2. Coloca una ficha a cada lado. 3. Anticipa y abre sus registros. Puedes cambiar el par y volver a probar.</p><fieldset><legend>Mi pregunta</legend>${buttons(biologyQuestions,s.question,'data-biology-question')}</fieldset><div class="balance-records"><fieldset><legend>Ficha izquierda</legend>${buttons(options,s.left,'data-biology-left')}</fieldset><fieldset><legend>Ficha derecha</legend>${buttons(options,s.right,'data-biology-right')}</fieldset></div><div class="balance-records">${card(s.left,'Izquierda',!!s.tested)}${card(s.right,'Derecha',!!s.tested)}</div><fieldset><legend>Antes de abrir: ¿qué anticipas sobre las hojas nuevas?</legend>${buttons(biologyPredictions,s.prediction,'data-biology-prediction')}</fieldset><div class="controls"><button type="button" class="action primary" id="biology-test" ${s.prediction?'':'disabled'}>Abrir estos registros</button><button type="button" class="action secondary" id="biology-hint">Una pista para comparar</button></div>${s.hint?'<p id="biology-hint-text" tabindex="-1" role="status">Para comparar horas de luz, busca dos fichas con la misma agua y distinta duración de luz. Para comparar agua, mantén las horas de luz. No necesitas adivinar las cifras.</p>':''}${s.tested?`<div id="biology-result" tabindex="-1" role="status"><p>Registro inventado: izquierda ${compareBiology(s.tested).left}, derecha ${compareBiology(s.tested).right} hojas nuevas. ${s.prediction==='unknown'?'Habías dejado abierta la predicción; ahora hay datos para describir.':compareBiology(s.tested).outcome===s.prediction?'Coincide con tu anticipación.':'Difiere de tu anticipación; revisarla forma parte de investigar.'}</p></div><fieldset><legend>¿Cómo interpretarías esta comparación?</legend>${buttons(biologyReasons,s.reason,'data-biology-reason')}</fieldset><button type="button" class="action secondary" id="biology-explain" ${s.reason?'':'disabled'}>Contrastar mi explicación</button>${s.reviewed?`<p role="status" id="biology-feedback" tabindex="-1">${explainBiology(s)}</p><button type="button" class="action primary" id="biology-close">Comparar mi inicio y cerrar</button>`:''}`:''}`}<button type="button" class="action secondary" id="biology-back">Volver a la guía del taller</button></section>`;
 const bind=(id,fn)=>root.querySelector('#'+id)?.addEventListener('click',fn);for(const field of ['question','left','right','prediction'])root.querySelectorAll(`[data-biology-${field}]`).forEach(b=>b.onclick=()=>{changeBiology(s,field,b.getAttribute('data-biology-'+field));redraw(`[data-biology-${field}="${s[field]}"]`);});root.querySelectorAll('[data-biology-reason]').forEach(b=>b.onclick=()=>{s.reason=b.dataset.biologyReason;s.reviewed=false;redraw(`[data-biology-reason="${s.reason}"]`);});bind('biology-test',()=>{if(testBiology(s))redraw('#biology-result');});bind('biology-hint',()=>{s.hint=true;redraw('#biology-hint-text');});bind('biology-explain',()=>{s.reviewed=true;redraw('#biology-feedback');});bind('biology-close',()=>{if(closeBiology(s))redraw();});bind('biology-revise',()=>{s.page='edit';redraw();});bind('biology-start',()=>{s.page='edit';redraw();});bind('biology-back',()=>{if(back){s.open=false;back();}else{s.page='guide';redraw();}});bind('biology-finish',()=>finish());
}
